atlas:
PREFIX fb: <http://phenomebrowser.net/flopo/browse#>
SELECT ?og ?tg (COUNT(DISTINCT ?t) AS ?taxa) (COUNT(?r) AS ?n) WHERE {
  ?r a fb:TraitRecord ; fb:organGroup ?og ; fb:traitGroup ?tg ; fb:taxon ?t } GROUP BY ?og ?tg

traitValues:
PREFIX fb: <http://phenomebrowser.net/flopo/browse#>
SELECT (STRAFTER(STR(?og), "#") AS ?o) (STRAFTER(STR(?tg), "#") AS ?g) (STRAFTER(STR(?b), "/obo/") AS ?p) (STRAFTER(STR(?q), "/obo/") AS ?v) (COUNT(DISTINCT ?t) AS ?n) WHERE {
  ?r a fb:TraitRecord ; fb:organGroup ?og ; fb:traitGroup ?tg ; fb:bearer ?b ; fb:quality ?q ; fb:taxon ?t ; fb:negated false }
GROUP BY ?og ?tg ?b ?q HAVING (COUNT(DISTINCT ?t) > 1) ORDER BY DESC(?n)

positionedValues:
PREFIX fb: <http://phenomebrowser.net/flopo/browse#>
SELECT (STRAFTER(STR(?pp), "/obo/") AS ?p) (STRAFTER(STR(?q), "/obo/") AS ?v) (COUNT(DISTINCT ?t) AS ?n) WHERE {
  ?r a fb:TraitRecord ; fb:positionedPart ?pp ; fb:quality ?q ; fb:taxon ?t ; fb:negated false }
GROUP BY ?pp ?q HAVING (COUNT(DISTINCT ?t) > 1) ORDER BY DESC(?n)
